#include "../RahiTuber/MaxPlushMesh.h"
#include <stdexcept>
#include <iostream>
int main(){sf::Image front,back;front.create(256,256,sf::Color::Transparent);back.create(256,256,sf::Color::Transparent);
 for(int y=0;y<256;y++)for(int x=0;x<256;x++){float dx=(x-128.f)/96,dy=(y-128.f)/112,d=std::sqrt(dx*dx+dy*dy);int alpha=int(std::clamp((1-d)*96.f,0.f,1.f)*255);auto a=sf::Uint8(alpha);front.setPixel(x,y,{sf::Uint8(70*alpha/255),sf::Uint8(170*alpha/255),a,a});back.setPixel(x,y,{sf::Uint8(35*alpha/255),sf::Uint8(82*alpha/255),sf::Uint8(140*alpha/255),a});}
 auto contour=MaxPlushContour(front.getPixelsPtr(),256,256,0,0,256,256);sf::Texture ft,bt;ft.loadFromImage(front);bt.loadFromImage(back);ft.setSmooth(true);bt.setSmooth(true);
 sf::Image sheet;sheet.create(1024,256,{12,20,35});int index=0;
 for(float yaw:{0.f,45.f,90.f,180.f}){sf::RenderTexture target;if(!target.create(256,256))throw std::runtime_error("Cannot create render target");target.clear(sf::Color::Transparent);sf::RenderStates state;state.blendMode=sf::BlendMode(sf::BlendMode::One,sf::BlendMode::OneMinusSrcAlpha);state.texture=&bt;target.draw(MaxPlushMesh(contour,contour,{0,0,256,256},.45f,yaw,true,sf::Color::White),state);state.texture=&ft;target.draw(MaxPlushMesh(contour,contour,{0,0,256,256},.45f,yaw,false,sf::Color::White),state);target.display();auto result=target.getTexture().copyToImage();auto center=result.getPixel(128,128);if(yaw==0&&(center.g<165||center.a<250))throw std::runtime_error("Front PNG or alpha changed");if(yaw==180&&(center.b<135||center.a<250))throw std::runtime_error("Back PNG not shown");int first=-1,last=-1;for(int x=0;x<256;x++)if(result.getPixel(x,128).a>180){if(first<0)first=x;last=x;}if(first<0)throw std::runtime_error("Empty plush view");for(int x=first+3;x<last-3;x++)if(result.getPixel(x,128).a<150)throw std::runtime_error("Visible gap in joined surfaces at turn "+std::to_string(yaw));sheet.copy(result,index++*256,0);}
 if(!sheet.saveToFile("plush-render-check.png"))throw std::runtime_error("Cannot save render check");std::cout<<"PASS: front, rear, 45-degree and side views with no interior seam gap\n";}
